function validate([n, roads]) {
  if (!Number.isInteger(n) || n < 2 || n > 50000) return 'n is between 2 and 50000.';
  if (roads.length < 1 || roads.length > 50000) return 'roads needs 1 to 50000 entries.';
  const seen = new Set();
  for (const road of roads) {
    if (!Array.isArray(road) || road.length !== 2) return 'Each road is a pair [a, b].';
    const [a, b] = road;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Road endpoints are cities 0 to n - 1.';
    if (a === b) return 'A road connects two different cities.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (seen.has(key)) return 'No road may appear twice.';
    seen.add(key);
  }
  return null;
}

