function maximumImportance(n, roads) {
  const value = new Array(n).fill(0);
  const used = new Array(n + 1).fill(false);
  let best = 0;
  const place = (city) => {
    if (city === n) {
      let sum = 0;
      for (const [a, b] of roads) sum += value[a] + value[b];
      if (sum > best) best = sum;
      return;
    }
    for (let v = 1; v <= n; v++) {
      if (used[v]) continue;
      used[v] = true;
      value[city] = v;
      place(city + 1);
      used[v] = false;
    }
  };
  place(0);
  return best;
}

