function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const orient = (a, b) => (rand() < 0.5 ? [a, b] : [b, a]);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  if (size === 'large') {
    if (rand() < 0.5) {
      // A dense graph on 64 cities: 2000 of its 2016 possible roads.
      const n = 64, pairs = [];
      for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) pairs.push(orient(a, b));
      return [n, shuffle(pairs).slice(0, 2000)];
    }
    const n = int(2000, 50000), seen = new Set(), roads = [];
    while (roads.length < 2000) {
      const a = int(0, n - 1), b = int(0, n - 1);
      if (a === b) continue;
      const key = Math.min(a, b) * n + Math.max(a, b);
      if (seen.has(key)) continue;
      seen.add(key);
      roads.push(orient(a, b));
    }
    return [n, roads];
  }
  const n = int(2, 7), pairs = [];
  for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) pairs.push(orient(a, b));
  return [n, shuffle(pairs).slice(0, int(1, pairs.length))];
}
